#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
static bool validate(const bowling*g,bool*complete){size_t i=0;*complete=false;for(int frame=0;frame<10;frame++){if(i>=g->count)return true;int a=g->rolls[i++];if(a<0||a>10)return false;if(frame<9&&a==10)continue;if(i>=g->count)return true;int b=g->rolls[i++];if(b<0||b>10||(a<10&&a+b>10))return false;if(frame==9){if(a==10||a+b==10){if(i>=g->count)return true;int c=g->rolls[i++];if(c<0||c>10||(a==10&&b<10&&b+c>10))return false;}*complete=true;return i==g->count;}}return true;}bool roll(bowling*g,int p){bool complete;if(!validate(g,&complete)||complete||g->count>=21)return false;g->rolls[g->count++]=p;if(!validate(g,&complete)){g->count--;return false;}return true;}bool score(const bowling*g,int*out){bool complete;if(!validate(g,&complete)||!complete)return false;int total=0;size_t i=0;for(int f=0;f<10;f++){int a=g->rolls[i];if(a==10){total+=10+g->rolls[i+1]+g->rolls[i+2];i++;}else{int b=g->rolls[i+1];total+=a+b;if(a+b==10)total+=g->rolls[i+2];i+=2;}}*out=total;return true;}

